// Generated by ppl for __PPL_WASM__ (wasm32-browser, WasmGC backend; decision 264). ES module.
//
//   import init from "./__PPL_BASE__.js"
//   const app = await init()          // runs the program
//   await app.done                     // its exit code
//
// Under Node.js, `node __PPL_BASE__.js` runs the program and exits with its exit code.

const WASM = new URL("./__PPL_WASM__", import.meta.url);
const FILE = __PPL_FILE__;
const isNode = typeof process === "object" && !!process?.versions?.node;

class Exit {
  constructor(code) {
    this.code = code;
  }
}

async function compile(source) {
  if (source instanceof WebAssembly.Module) return source;
  if (source instanceof ArrayBuffer || ArrayBuffer.isView(source)) return WebAssembly.compile(source);
  const url = new URL(source ?? WASM, import.meta.url);
  if (url.protocol === "file:") {
    const fs = await import("node:fs/promises");
    return WebAssembly.compile(await fs.readFile(url));
  }
  return WebAssembly.compileStreaming(fetch(url));
}

/** Output: buffered, written to the process's streams (Node.js) or the console. */
async function sinks(options) {
  const fs = isNode ? await import("node:fs") : null;
  const make = (fd, given) => {
    let buf = "";
    const write = (s) => {
      if (given) return given(new TextEncoder().encode(s));
      if (fs) {
        const b = Buffer.from(s);
        let off = 0;
        while (off < b.length) {
          try {
            off += fs.writeSync(fd, b, off);
          } catch (e) {
            if (e.code !== "EAGAIN") throw e;
          }
        }
      } else {
        for (const line of s.split("\n").slice(0, -1)) (fd === 2 ? console.error : console.log)(line);
      }
    };
    return {
      put(s) {
        buf += s;
        if (buf.length > 65536) this.flush();
      },
      flush() {
        if (fs || given) {
          if (buf) write(buf);
          buf = "";
        } else {
          const nl = buf.lastIndexOf("\n");
          if (nl >= 0) {
            write(buf.slice(0, nl + 1));
            buf = buf.slice(nl + 1);
          }
        }
      },
    };
  };
  return { out: make(1, options.stdout), err: make(2, options.stderr) };
}

export default async function init(options = {}) {
  const module = await compile(options.module);
  const { out, err } = await sinks(options);
  const enc = new TextEncoder();
  const dec = new TextDecoder();
  let ex;
  const str = (r) => {
    const n = ex.str_len(r);
    const b = new Uint8Array(n);
    for (let i = 0; i < n; i++) b[i] = ex.str_byte(r, i);
    return dec.decode(b);
  };
  const mk = (s) => {
    const b = enc.encode(s);
    const r = ex.str_new(b.length);
    for (let i = 0; i < b.length; i++) ex.str_put(r, i, b[i]);
    return r;
  };
  const int = (v, unsigned) => (unsigned ? BigInt.asUintN(64, v) : v).toString();
  const f32 = (x) => {
    if (!Number.isFinite(x)) return String(x);
    for (let k = 1; k <= 9; k++) {
      const s = Number(x.toPrecision(k));
      if (Math.fround(s) === x) return String(s);
    }
    return String(x);
  };
  // Format specs: `ppl_rt.c`'s `ppl_fmt_*` (spec fields as `PplFmt`).
  const spec = (fill, align, sign, alt, zero, width, prec, kind) => ({ fill, align, sign, alt, zero, width, prec, kind });
  /** Shortest round-tripping digits of `a` > 0 and its decimal exponent `n` (a = 0.d… × 10^n). */
  const shortest = (a, isF32) => {
    let x = a;
    if (isF32) {
      for (let k = 1; k <= 9; k++) {
        const t = Number(a.toPrecision(k));
        if (Math.fround(t) === a) {
          x = t;
          break;
        }
      }
    }
    const [m, e] = x.toExponential().split("e");
    return { digits: m.replace(".", ""), n: Number(e) + 1 };
  };
  const shortestFixed = (a, isF32) => {
    if (a === 0) return "0";
    const { digits, n } = shortest(a, isF32);
    const k = digits.length;
    if (n <= 0) return "0." + "0".repeat(-n) + digits;
    if (n >= k) return digits + "0".repeat(n - k);
    return digits.slice(0, n) + "." + digits.slice(n);
  };
  /** `toFixed` as C's `%.*f`: an exact tie rounds to even (JavaScript rounds it up). */
  const fixed = (a, p) => {
    const s = a.toFixed(p);
    if (p > 80) return s;
    const longer = a.toFixed(Math.min(100, p + 20));
    const tail = longer.slice(longer.length - 20);
    if (tail[0] !== "5" || !/^50*$/.test(tail)) return s;
    // A tie: the digits kept are `longer` cut before the 5; round up only if the last is odd.
    const kept = longer.slice(0, longer.length - 20).replace(/\.$/, "");
    const last = kept.replace(".", "").slice(-1);
    return Number(last) % 2 === 0 ? kept : s;
  };
  const expForm = (s) => {
    const [m, e] = s.split("e");
    return [m, Number(e)];
  };
  const floatBody = (a, isF32, f) => {
    const p = f.prec;
    switch (f.kind) {
      case 8:
        return p >= 0 ? fixed(a, p) : shortestFixed(a, isF32);
      case 6:
      case 7: {
        const E = f.kind === 7 ? "E" : "e";
        if (p >= 0) {
          const [m, e] = expForm(a.toExponential(p));
          return `${m}${E}${e}`;
        }
        if (a === 0) return `0${E}0`;
        const { digits, n } = shortest(a, isF32);
        const m = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
        return `${m}${E}${n - 1}`;
      }
      case 9: {
        const y = a * 100;
        return (p >= 0 ? fixed(y, p) : shortestFixed(y, false)) + "%";
      }
      default:
        return p >= 0 ? fixed(a, p) : isF32 ? f32(a) : String(a);
    }
  };
  const pad = (neg, prefix, body, numeric, f) => {
    const sign = neg ? "-" : numeric && f.sign === 1 ? "+" : numeric && f.sign === 2 ? " " : "";
    const len = sign.length + prefix.length + [...body].length;
    const width = f.width < 0 ? 0 : f.width;
    if (len >= width) return sign + prefix + body;
    if (f.zero && numeric) return sign + prefix + "0".repeat(width - len) + body;
    const align = f.align || (numeric ? 2 : 1);
    const missing = width - len;
    const left = align === 1 ? 0 : align === 2 ? missing : Math.floor(missing / 2);
    const fill = String.fromCodePoint(f.fill);
    return fill.repeat(left) + sign + prefix + body + fill.repeat(missing - left);
  };
  const fmtInt = (neg, mag, f, asFloat) => {
    if (f.kind >= 6 && f.kind <= 9) return pad(asFloat < 0, "", floatBody(Math.abs(asFloat), false, f), true, f);
    let body, prefix = "";
    switch (f.kind) {
      case 2: body = mag.toString(16); if (f.alt) prefix = "0x"; break;
      case 3: body = mag.toString(16).toUpperCase(); if (f.alt) prefix = "0x"; break;
      case 4: body = mag.toString(8); if (f.alt) prefix = "0o"; break;
      case 5: body = mag.toString(2); if (f.alt) prefix = "0b"; break;
      default: body = mag.toString();
    }
    return pad(neg, prefix, body, true, f);
  };
  const quoted = (s, q) => {
    let out = q;
    for (const ch of s) {
      const c = ch.codePointAt(0);
      if (ch === "\\") out += "\\\\";
      else if (ch === "\n") out += "\\n";
      else if (ch === "\r") out += "\\r";
      else if (ch === "\t") out += "\\t";
      else if (c === 0) out += "\\0";
      else if (ch === q) out += "\\" + q;
      else if (c < 0x20 || c === 0x7f) out += `\\u{${c.toString(16)}}`;
      else out += ch;
    }
    return out + q;
  };
  const fmtSpec = {
    fmt_spec_i64(v, unsigned, ...a) {
      const f = spec(...a);
      if (unsigned) return mk(fmtInt(false, BigInt.asUintN(64, v), f, Number(BigInt.asUintN(64, v))));
      return mk(fmtInt(v < 0n, v < 0n ? -v : v, f, Number(v)));
    },
    fmt_spec_f64(v, isF32, ...a) {
      const f = spec(...a);
      if (Number.isNaN(v)) return mk(pad(false, "", "NaN", true, f));
      const body = Number.isFinite(v) ? floatBody(Math.abs(v), isF32 !== 0, f) : "Infinity";
      return mk(pad(v < 0, "", body, true, f));
    },
    fmt_spec_str(r, ...a) {
      const f = spec(...a);
      const t = str(r);
      const cps = [...t];
      const body = f.kind === 10 ? quoted(t, '"') : f.prec >= 0 && f.prec < cps.length ? cps.slice(0, f.prec).join("") : t;
      return mk(pad(false, "", body, false, f));
    },
    fmt_spec_char(c, ...a) {
      const f = spec(...a);
      const ch = String.fromCodePoint(c);
      return mk(pad(false, "", f.kind === 10 ? quoted(ch, "'") : ch, false, f));
    },
    fmt_spec_bool(b, ...a) {
      return mk(pad(false, "", b ? "true" : "false", false, spec(...a)));
    },
  };
  const ppl = {
    ...fmtSpec,
    print_str: (r) => out.put(str(r)),
    print_i64: (v, u) => out.put(int(v, u)),
    print_f64: (x) => out.put(String(x)),
    print_f32: (x) => out.put(f32(x)),
    print_char: (c) => out.put(String.fromCodePoint(c)),
    print_nl: () => out.put("\n"),
    fmt_i64: (v, u) => mk(int(v, u)),
    fmt_f64: (x) => mk(String(x)),
    fmt_f32: (x) => mk(f32(x)),
    fmt_char: (c) => mk(String.fromCodePoint(c)),
    panic(msg, line, col) {
      out.flush();
      err.put(`panic: ${str(msg)}\n` + (line ? `  at ${FILE}:${line}:${col}\n` : ""));
      err.flush();
      throw new Exit(101);
    },
    pow_f64: Math.pow,
    clock_ms: () => BigInt(Math.floor(performance.now())),
  };
  const instance = await WebAssembly.instantiate(module, { ppl });
  ex = instance.exports;
  let code = 0;
  try {
    ex.start();
  } catch (e) {
    if (!(e instanceof Exit)) {
      out.flush();
      throw e;
    }
    code = e.code;
  }
  out.flush();
  err.flush();
  return { instance, done: Promise.resolve(code) };
}

// (Real paths: the module's is resolved, `argv[1]` may go through a symlink, as macOS's
// temporary directory does.)
const isMain =
  isNode &&
  !!import.meta.filename &&
  !!process.argv[1] &&
  (await import("node:fs")).realpathSync(process.argv[1]) === import.meta.filename;
if (isMain) {
  try {
    const app = await init();
    process.exitCode = await app.done;
  } catch (e) {
    console.error(`fatal: ${e?.stack ?? e}`);
    process.exitCode = 134;
  }
}
